import{_ as l,o as a,c as e,O as r}from"./chunks/framework.db831a78.js";const p=JSON.parse('{"title":"Java 面试刷题清单","description":"","frontmatter":{},"headers":[],"relativePath":"interview/后端/Java/index.md","filePath":"interview/后端/Java/index.md","lastUpdated":null}'),t={name:"interview/后端/Java/index.md"};function o(n,i,h,s,u,d){return a(),e("div",null,i[0]||(i[0]=[r('<h1 id="java-面试刷题清单" tabindex="-1">Java 面试刷题清单 <a class="header-anchor" href="#java-面试刷题清单" aria-label="Permalink to &quot;Java 面试刷题清单&quot;">​</a></h1><blockquote><p>适合按顺序刷。共 10 大模块，覆盖 Java 后端面试的高频考点。</p></blockquote><h2 id="常问等级说明" tabindex="-1">常问等级说明 <a class="header-anchor" href="#常问等级说明" aria-label="Permalink to &quot;常问等级说明&quot;">​</a></h2><ul><li>★★★ = 高频必考（几乎每次面试都会问到，务必能流畅作答）</li><li>★★☆ = 中频常见（多数面试会涉及，建议掌握）</li><li>★☆☆ = 低频了解（时间有限可快速过一遍，能说个大概即可）</li></ul><blockquote><p>前端转全栈重点：Java 基础里的值传递、final、类初始化顺序、Java 8 新特性、集合选型；多线程的 synchronized 与 Lock 区别、sleep 与 wait 区别；计算机网络里的跨域 CORS。这些是前端背景最容易卡壳、面试官又爱问的。</p></blockquote><h2 id="目录" tabindex="-1">目录 <a class="header-anchor" href="#目录" aria-label="Permalink to &quot;目录&quot;">​</a></h2><ol><li><a href="./01-Java基础">Java 基础</a></li><li><a href="./02-JVM">JVM</a></li><li><a href="./03-多线程并发">多线程并发</a></li><li><a href="./04-Spring全家桶">Spring 全家桶</a></li><li><a href="./05-MySQL">MySQL</a></li><li><a href="./06-中间件">中间件（Redis / MQ）</a></li><li><a href="./07-计算机网络">计算机网络</a></li><li><a href="./08-分布式高并发">分布式 &amp; 高并发</a></li><li><a href="./09-项目算法设计模式">项目实战、算法、设计模式</a></li><li><a href="./10-工具运维">工具 &amp; 运维</a></li></ol><h2 id="一、java-基础" tabindex="-1">一、Java 基础 <a class="header-anchor" href="#一、java-基础" aria-label="Permalink to &quot;一、Java 基础&quot;">​</a></h2><ul><li>基本数据类型和包装类区别、Integer 缓存机制、自动装箱拆箱 ★★★</li><li>面向对象三大特性、抽象类和接口区别 ★★★</li><li>String / StringBuilder / StringBuffer 区别；String 不可变原理、常量池、intern() ★★★</li><li>ArrayList / LinkedList 底层实现、扩容机制 ★★★</li><li>HashMap 底层原理，1.7 与 1.8 区别；红黑树转换条件；扰动函数；扩容机制 ★★★</li><li>ConcurrentHashMap 1.7 与 1.8 实现区别 ★★★</li><li>Hashtable 与 HashMap 对比 ★★☆</li><li>异常体系、受检/非受检异常、try-finally / try-with-resources ★★★</li><li>泛型原理、泛型擦除；?、? extends、? super 通配符 ★★★</li><li>反射机制、获取 Class 对象的几种方式、反射优缺点 ★★★</li><li>注解、元注解、自定义注解 ★★☆</li><li>BIO / NIO / AIO 区别；Buffer、Channel ★★★</li><li>== 与 equals、hashCode 契约 ★★★</li><li>深拷贝与浅拷贝、序列化 serialVersionUID ★★☆</li><li>BigDecimal 与浮点精度 ★★★</li><li>四种内部类 ★☆☆</li><li>枚举原理 ★★☆</li><li>函数式接口、Lambda、Stream ★★★</li><li>值传递与引用传递（前端转全栈必考）★★★</li><li>final、finally、finalize 区别 ★★★</li><li>Object 类常用方法 ★★☆</li><li>类初始化顺序、静态变量/代码块 ★★☆</li><li>Comparable 与 Comparator 区别 ★★☆</li><li>Java 8 新特性汇总、Optional ★★★</li><li>集合框架选型总结 ★★★</li></ul><h2 id="二、jvm" tabindex="-1">二、JVM <a class="header-anchor" href="#二、jvm" aria-label="Permalink to &quot;二、JVM&quot;">​</a></h2><ul><li>JVM 内存区域划分、各区域作用、哪些会 OOM ★★★</li><li>对象创建过程、对象内存布局、对象头 ★★☆</li><li>如何判断对象是垃圾；四种引用（强/软/弱/虚）★★★</li><li>GC 三大算法：标记清除、复制、标记整理 ★★★</li><li>常见垃圾收集器：Serial、Parallel、CMS、G1、ZGC ★★★</li><li>类加载全过程、双亲委派模型、破坏双亲委派 ★★★</li><li>OOM 常见场景、jmap、jstack 工具作用 ★★★</li><li>逃逸分析、栈上分配 ★★☆</li><li>JVM 常用调优参数 ★★☆</li><li>JMM 与 JVM 内存模型的区别 ★★★</li><li>元空间 vs 永久代、字符串常量池位置 ★★☆</li><li>直接内存 ★★☆</li><li>三色标记、对象进入老年代条件、STW ★★☆</li></ul><h2 id="三、多线程并发" tabindex="-1">三、多线程并发 <a class="header-anchor" href="#三、多线程并发" aria-label="Permalink to &quot;三、多线程并发&quot;">​</a></h2><ul><li>线程状态、创建线程的几种方式、start() 和 run() 区别 ★★★</li><li>synchronized 底层原理、锁升级过程（偏向锁-轻量级-重量级）★★★</li><li>volatile 作用、可见性/原子性/有序性、happens-before ★★★</li><li>AQS 原理、ReentrantLock 公平/非公平锁、Condition ★★★</li><li>ThreadPoolExecutor 七大参数、四种拒绝策略、为什么不推荐 Executors ★★★</li><li>线程池参数如何按业务设置、核心线程/空闲线程 ★★★</li><li>CountDownLatch / CyclicBarrier / Semaphore ★★★</li><li>ConcurrentHashMap、CopyOnWriteArrayList 原理 ★★★</li><li>死锁四个条件、如何避免死锁、活锁、饥饿 ★★★</li><li>线程安全问题产生原因 ★★☆</li><li>ThreadLocal 原理与内存泄漏 ★★★</li><li>CAS 原理与 ABA 问题 ★★★</li><li>原子类 AtomicInteger、LongAdder ★★☆</li><li>CompletableFuture 异步编排 ★★★</li><li>JMM 内存屏障、指令重排 ★★☆</li><li>BlockingQueue、线程中断 interrupt ★★☆</li><li>synchronized 与 ReentrantLock 区别（前端转全栈必考）★★★</li><li>sleep() 与 wait() 区别 ★★★</li><li>volatile 与 synchronized 区别 ★★☆</li><li>wait/notify 线程协作机制 ★★☆</li></ul><h2 id="四、spring-全家桶" tabindex="-1">四、Spring 全家桶 <a class="header-anchor" href="#四、spring-全家桶" aria-label="Permalink to &quot;四、Spring 全家桶&quot;">​</a></h2><ul><li>IOC 容器原理、Bean 完整生命周期 ★★★</li><li>Bean 作用域、BeanFactory 与 ApplicationContext 区别 ★★★</li><li>AOP 原理：JDK 动态代理、CGLIB、五种通知类型 ★★★</li><li>@Transactional 传播行为、隔离级别、事务失效场景、实现原理 ★★★</li><li>SpringBoot 自动配置原理、条件注解、启动流程 ★★★</li><li>全局异常处理 ★★★</li><li>@Configuration、@Bean ★★☆</li><li>SpringMVC 请求流程、Filter 与 Interceptor 区别、@RequestParam 与 @RequestBody ★★★</li><li>Nacos/Eureka、Feign、Gateway、Sentinel、分布式事务 ★★★</li><li>@Autowired 与 @Resource 区别 ★★★</li><li>三级缓存解决循环依赖 ★★★</li><li>AOP 失效场景（同类调用）★★☆</li><li>Spring 用到的设计模式 ★★☆</li><li>Spring Boot Starter 机制、MyBatis #{} 与 ${} ★★★</li><li>Spring、SpringBoot、SpringCloud 区别（前端转全栈必考）★★★</li></ul><h2 id="五、mysql" tabindex="-1">五、MySQL <a class="header-anchor" href="#五、mysql" aria-label="Permalink to &quot;五、MySQL&quot;">​</a></h2><ul><li>InnoDB 索引 B+ 树结构、聚簇/非聚簇索引 ★★★</li><li>联合索引最左前缀、索引失效场景 ★★★</li><li>事务 ACID、四种隔离级别、MVCC ★★★</li><li>redo log、undo log、binlog ★★★</li><li>InnoDB 锁机制：行锁、表锁、意向锁、间隙锁、幻读 ★★★</li><li>explain 字段含义、慢查询优化 ★★★</li><li>主从复制、读写分离、分库分表 ★★★</li><li>索引下推 ICP、覆盖索引 ★★☆</li><li>为什么用 B+ 树不用 B 树/哈希/跳表 ★★☆</li><li>count(*) 优化、深分页 ★★★</li><li>三大范式、InnoDB vs MyISAM ★★☆</li><li>隐式类型转换导致索引失效 ★★☆</li></ul><h2 id="六、中间件" tabindex="-1">六、中间件 <a class="header-anchor" href="#六、中间件" aria-label="Permalink to &quot;六、中间件&quot;">​</a></h2><h3 id="redis" tabindex="-1">Redis <a class="header-anchor" href="#redis" aria-label="Permalink to &quot;Redis&quot;">​</a></h3><ul><li>常用数据结构及使用场景 ★★★</li><li>RDB 与 AOF 持久化对比 ★★★</li><li>过期淘汰策略 ★★★</li><li>缓存穿透、缓存击穿、缓存雪崩 ★★★</li><li>分布式锁实现及问题 ★★★</li><li>哨兵、集群模式 ★★★</li><li>底层数据结构（SDS、跳表、listpack 等）★★☆</li><li>为什么快（单线程、IO 多路复用、内存）★★★</li><li>大 key、热 key ★★☆</li><li>缓存一致性（延迟双删、Canal）★★★</li><li>布隆过滤器、Bitmap/HyperLogLog/GEO ★★☆</li><li>Redis 6.0 多线程 ★★☆</li></ul><h3 id="mq-rabbitmq-kafka-rocketmq" tabindex="-1">MQ（RabbitMQ / Kafka / RocketMQ） <a class="header-anchor" href="#mq-rabbitmq-kafka-rocketmq" aria-label="Permalink to &quot;MQ（RabbitMQ / Kafka / RocketMQ）&quot;">​</a></h3><ul><li>使用消息队列的好处、场景 ★★★</li><li>消息丢失、重复消费、积压处理 ★★★</li><li>RabbitMQ 交换机类型、Kafka 高可用 ★★★</li><li>各 MQ 对比选型 ★★☆</li><li>顺序消息、事务消息、延迟消息、死信队列 ★★☆</li></ul><h2 id="七、计算机网络" tabindex="-1">七、计算机网络 <a class="header-anchor" href="#七、计算机网络" aria-label="Permalink to &quot;七、计算机网络&quot;">​</a></h2><ul><li>HTTP1.1 / HTTP2 / HTTP3 区别 ★★★</li><li>HTTPS 加密原理、TLS 握手 ★★★</li><li>GET 与 POST 区别 ★★★</li><li>Cookie / Session / Token 区别 ★★★</li><li>TCP 三次握手、四次挥手、为什么不能两次握手 ★★★</li><li>TCP 滑动窗口、拥塞控制、TCP 与 UDP 区别 ★★★</li><li>常见 HTTP 状态码 ★★☆</li><li>OSI 七层 / TCP/IP 四层模型 ★★★</li><li>输入 URL 到页面展示全流程 ★★★</li><li>DNS 解析、Session 共享、JWT 结构 ★★★</li><li>跨域 CORS 原理与解决方案（前端转全栈必考）★★★</li></ul><h2 id="八、分布式-高并发" tabindex="-1">八、分布式 &amp; 高并发 <a class="header-anchor" href="#八、分布式-高并发" aria-label="Permalink to &quot;八、分布式 &amp; 高并发&quot;">​</a></h2><ul><li>CAP、BASE 理论 ★★★</li><li>分布式事务：2PC、3PC、TCC、SAGA、本地消息表、可靠消息最终一致性 ★★★</li><li>分布式 ID 生成方案 ★★★</li><li>接口幂等性设计 ★★★</li><li>限流、熔断、降级实现方式 ★★★</li><li>限流算法（计数器/滑动窗口/令牌桶/漏桶）★★★</li><li>负载均衡算法、一致性哈希 ★★★</li><li>分布式锁方案对比（Redis/ZK/DB）★★★</li><li>链路追踪 ★★☆</li></ul><h2 id="九、项目实战、算法、设计模式" tabindex="-1">九、项目实战、算法、设计模式 <a class="header-anchor" href="#九、项目实战、算法、设计模式" aria-label="Permalink to &quot;九、项目实战、算法、设计模式&quot;">​</a></h2><ul><li>项目中最难技术点、怎么解决 ★★★</li><li>线上 CPU 飙升、OOM、接口超时排查 ★★★</li><li>手写单例模式（懒汉、饿汉、双重校验锁）★★★</li><li>常见设计模式、Spring 用到哪些 ★★☆</li><li>算法：链表反转、二分查找、两数之和、栈队列 ★★★</li><li>排序算法 ★★★</li><li>设计模式六大原则（SOLID、开闭、里氏替换）★★☆</li></ul><h2 id="十、工具-运维" tabindex="-1">十、工具 &amp; 运维 <a class="header-anchor" href="#十、工具-运维" aria-label="Permalink to &quot;十、工具 &amp; 运维&quot;">​</a></h2><ul><li>Git 常用命令、merge 与 rebase ★★☆</li><li>Maven 依赖冲突 ★★☆</li><li>Docker 基础概念 ★★☆</li><li>Linux 常用命令：进程、日志、端口、内存 CPU ★★★</li><li>XSS、CSRF、密码加密 ★★★</li><li>SQL 注入、越权 ★★★</li><li>线上排查完整流程、线程 dump 分析 ★★★</li><li>JVM 调优参数、日志框架、监控体系 ★★☆</li></ul>',30)]))}const m=l(t,[["render",o]]);export{p as __pageData,m as default};
